<?php
declare(strict_types=1);
require __DIR__.'/bootstrap/app.php';
use App\Core\Auth;use App\Core\Database;use App\Core\Security;use App\Core\Url;use App\Learning\MeetingPlannerService;
$pdo=Database::connect();$user=Auth::user($pdo);if(!$user)Security::redirect(Url::to('/login?redirect=meetings'));
$service=new MeetingPlannerService($pdo);$error='';$success='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){if(!Security::verifyCsrf($_POST['_csrf']??null))$error='Your session expired. Refresh and try again.';else try{$service->book((int)$user['id'],(int)($_POST['session_id']??0));$success='Your session booking is confirmed.';}catch(Throwable $e){$error=$e->getMessage();}}
$sessions=$service->sessionsForLearner((int)$user['id']);$csrf=Security::csrfToken();$esc=static fn($v)=>Security::escape((string)$v);
?>
<!doctype html><html lang="en"><head><base href="<?= $esc(Url::to('/')) ?>"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>My sessions · SmartStudyPro</title><link rel="stylesheet" href="<?= $esc(Url::to('/assets/vendor/bootstrap/css/bootstrap.min.css')) ?>"><link rel="stylesheet" href="<?= $esc(Url::to('/assets/css/device-responsive.css')) ?>"><style>body{background:#f5f6fb;color:#182033;font-family:system-ui,sans-serif}.wrap{max-width:1000px;margin:auto;padding:32px 18px}.session{background:#fff;border:1px solid #e3e7ef;border-radius:15px;padding:20px;margin:14px 0}.muted{color:#687386;font-size:13px}.btn-main{background:#ff7a00;color:#fff;border:0;border-radius:9px;padding:10px 15px;font-weight:700}</style></head><body><?php include __DIR__.'/nav.php';?><main class="wrap"><h1>My live & in-person sessions</h1><p class="muted">Only sessions attached to your active course enrolments appear here. Meeting links unlock after you book.</p><?php if($error):?><div class="alert alert-danger"><?= $esc($error) ?></div><?php endif;?><?php if($success):?><div class="alert alert-success"><?= $esc($success) ?></div><?php endif;?><?php foreach($sessions as $s):?><article class="session"><h2 class="h5"><?= $esc($s['course_title'].' · '.$s['title']) ?></h2><p class="muted"><?= $esc($s['mode'].' · '.$s['starts_at_utc'].' UTC · '.$s['timezone']) ?></p><?php if($s['provider']==='in_person'):?><p><strong><?= $esc($s['venue_name']) ?></strong><br><?= $esc($s['venue_address']) ?><br><?= $esc($s['venue_notes']) ?></p><?php else:?><p><?= $esc($s['provider']) ?> · <?= (int)$s['booked_count'] ?> booked<?= $s['capacity']!==null?' / '.(int)$s['capacity']:'' ?></p><?php endif;?><?php if($s['booking_status']==='confirmed'):?><span class="badge bg-success">Booked</span><?php if($s['join_url']!==''):?><a class="btn-main ms-2" href="<?= $esc($s['join_url']) ?>" target="_blank" rel="noopener noreferrer">Join meeting</a><?php endif;?><?php else:?><form method="post" class="mt-2"><input type="hidden" name="_csrf" value="<?= $esc($csrf) ?>"><input type="hidden" name="session_id" value="<?= (int)$s['id'] ?>"><button class="btn-main">Book session</button></form><?php endif;?></article><?php endforeach;?><?php if(!$sessions):?><div class="session">No upcoming sessions are scheduled for your enrolled courses yet.</div><?php endif;?></main></body></html>